  const SPAWN = '\n  spawnTimer -= dt;\n  if (spawnTimer <= 0) {\n    stars.push({ x: Math.random() * (canvas.width - 10), y: -10, w: 10, h: 10, speed: 120 });\n    spawnTimer = 0.5;\n  }\n  for (const s of stars) s.y += s.speed * dt;\n  stars = stars.filter((s) => s.y < canvas.height);\n';
  const HITLINE = '\n  if (stars.some((s) => hit(s, player))) state = "over";\n';
